func fail(_ message: String) -> Never {
    FileHandle.standardError.write(Data((message + "\n").utf8))
    exit(1)
}

guard CommandLine.arguments.count >= 4 else {
    fail("usage: extract_frames.swift VIDEO OUT_DIR TIME [TIME ...]")
}

let videoURL = URL(fileURLWithPath: CommandLine.arguments[1])
let outputURL = URL(fileURLWithPath: CommandLine.arguments[2], isDirectory: true)
let seconds = CommandLine.arguments.dropFirst(3).compactMap(Double.init)
try FileManager.default.createDirectory(at: outputURL, withIntermediateDirectories: true)

let asset = AVURLAsset(url: videoURL)
let generator = AVAssetImageGenerator(asset: asset)
generator.appliesPreferredTrackTransform = true
generator.requestedTimeToleranceBefore = .zero
generator.requestedTimeToleranceAfter = .zero

for second in seconds {
    let time = CMTime(seconds: second, preferredTimescale: 60000)
    do {
        let image = try generator.copyCGImage(at: time, actualTime: nil)
        let name = String(format: "%010.3f.jpg", second)
