    } catch {
        FileHandle.standardError.write(Data("failed at \(second): \(error)\n".utf8))
    }
}

import AppKit
import Foundation

guard CommandLine.arguments.count == 4 else {
    fputs("usage: contact_sheet.swift INPUT_DIR OUTPUT.jpg COLUMNS\n", stderr)
    exit(1)
}

let inputURL = URL(fileURLWithPath: CommandLine.arguments[1], isDirectory: true)
let outputURL = URL(fileURLWithPath: CommandLine.arguments[2])
let columns = Int(CommandLine.arguments[3]) ?? 4
let files = try FileManager.default.contentsOfDirectory(
    at: inputURL,
    includingPropertiesForKeys: nil
).filter { $0.pathExtension.lowercased() == "jpg" }.sorted { $0.lastPathComponent < $1.lastPathComponent }

let imageWidth = 320
let imageHeight = 180
let labelHeight = 24
let rows = Int(ceil(Double(files.count) / Double(columns)))
let canvas = NSImage(size: NSSize(width: columns * imageWidth, height: rows * (imageHeight + labelHeight)))
canvas.lockFocus()
NSColor.black.setFill()
NSRect(origin: .zero, size: canvas.size).fill()

let attrs: [NSAttributedString.Key: Any] = [
    .font: NSFont.monospacedDigitSystemFont(ofSize: 15, weight: .semibold),
    .foregroundColor: NSColor.white,
]

for (index, file) in files.enumerated() {
    guard let image = NSImage(contentsOf: file) else { continue }
    let column = index % columns
    let row = index / columns
    let x = column * imageWidth
    let y = (rows - row - 1) * (imageHeight + labelHeight)
    image.draw(in: NSRect(x: x, y: y + labelHeight, width: imageWidth, height: imageHeight))
    let label = file.deletingPathExtension().lastPathComponent
    label.draw(at: NSPoint(x: x + 6, y: y + 3), withAttributes: attrs)
}
canvas.unlockFocus()

