import AppKit
import Foundation
import Vision

guard CommandLine.arguments.count >= 2 else { exit(1) }

for path in CommandLine.arguments.dropFirst() {
    guard let image = NSImage(contentsOfFile: path),
          let data = image.tiffRepresentation,
          let bitmap = NSBitmapImageRep(data: data),
          let cgImage = bitmap.cgImage else { continue }
    // The broadcast keeps the percent counters in the lower game pane.
    let regions = [("L", CGRect(x: 430, y: 500, width: 260, height: 220)),
                   ("R", CGRect(x: 650, y: 500, width: 300, height: 220))]
    var values: [String] = []
    for (label, rect) in regions {
        guard let crop = cgImage.cropping(to: rect) else { continue }
        let request = VNRecognizeTextRequest()
        request.recognitionLevel = .fast
        request.usesLanguageCorrection = false
        request.minimumTextHeight = 0.08
        let handler = VNImageRequestHandler(cgImage: crop)
        try? handler.perform([request])
        let matches = (request.results ?? []).compactMap { $0.topCandidates(1).first?.string }
            .filter { $0.range(of: #"^\d{1,3}%?$"#, options: .regularExpression) != nil }
        if let value = matches.first { values.append("\(label)=\(value)") }
    }
    let name = URL(fileURLWithPath: path).deletingPathExtension().lastPathComponent
    print("\(name) \(values.joined(separator: " "))")
}

